const KEYS=Object.freeze({lastSession:'kana-last-session',daily:'kana-daily-ranking',vocabulary:'kana-vocabulary-progress-v1',skillMastery:'kana-skill-mastery-v1',nerd:'kana-nerd-ledger-v1',insanityStats:'kana-insanity-stats-v1',insanityRun:'kana-insanity-active-v1',endgames:'kana-endgames-v1',metaSystems:'kana-meta-systems-v1',dictionaryShard:'kana-dictionary-shard',grammarCapabilities:'kana-grammar-capabilities-v1',platformMeta:'kana-platform-meta-v2'});
