function clone(v){return v==null||typeof v!=='object'?v:JSON.parse(JSON.stringify(v));}
function nowIso(){return new Date().toISOString();}
function uuid(){if(typeof crypto!=='undefined'&&crypto.randomUUID)return crypto.randomUUID();return'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0,v=c==='x'?r:r&3|8;return v.toString(16);});}
