class MemoryStorage{constructor(seed={}){this.map=new Map(Object.entries(seed));}getItem(k){return this.map.has(k)?this.map.get(k):null;}setItem(k,v){this.map.set(k,String(v));}removeItem(k){this.map.delete(k);}}
class Logger{constructor(sink){this.sink=sink||(()=>{});}info(code,meta={}){this.sink({level:'info',code,meta:sanitize(meta)});}error(code,error,meta={}){this.sink({level:'error',code,message:String(error?.message||error),meta:sanitize(meta)});}}
