class SessionRepository{constructor(store){this.store=store;}getLast(){return this.store.read(KEYS.lastSession,null);}saveLast(value){return this.store.write(KEYS.lastSession,value);}getDaily(){return this.store.read(KEYS.daily,{});}saveDaily(value){return this.store.write(KEYS.daily,value);}}
class MasteryRepository{constructor(store){this.store=store;}getVocabulary(){return this.store.read(KEYS.vocabulary,{});}saveVocabulary(value){return this.store.write(KEYS.vocabulary,value);}getSkills(){return this.store.read(KEYS.skillMastery,{});}saveSkills(value){return this.store.write(KEYS.skillMastery,value);}getNerd(){return this.store.read(KEYS.nerd,null);}saveNerd(value){return this.store.write(KEYS.nerd,value);}}
class UnlockRepository{constructor(store){this.store=store;}getInsanityStats(fallback={}){return{...fallback,...(this.store.read(KEYS.insanityStats,{})||{})};}saveInsanityStats(value){return this.store.write(KEYS.insanityStats,value);}getInsanityRun(){return this.store.read(KEYS.insanityRun,null);}saveInsanityRun(value){return value?this.store.write(KEYS.insanityRun,value):this.store.remove(KEYS.insanityRun);}}
class RecordRepository{constructor(store){this.store=store;}getEndgames(fallback={}){return{...fallback,...(this.store.read(KEYS.endgames,{})||{})};}saveEndgames(value){return this.store.write(KEYS.endgames,value);}}
class SettingsRepository{constructor(store){this.store=store;}getDictionaryShard(){return Number(this.store.raw(KEYS.dictionaryShard))||0;}saveDictionaryShard(value){try{this.store.storage.setItem(KEYS.dictionaryShard,String(value));return true;}catch(error){this.store.logger.error('setting_write_failed',error,{key:KEYS.dictionaryShard});return false;}}getGrammarCapabilities(fallback=null){return this.store.read(KEYS.grammarCapabilities,fallback);}saveGrammarCapabilities(value){return this.store.write(KEYS.grammarCapabilities,value);}getMetaSystems(fallback=null){return this.store.read(KEYS.metaSystems,fallback);}saveMetaSystems(value){return this.store.write(KEYS.metaSystems,value);}}

const CONFLICT_POLICIES=Object.freeze({attempts:'append_only_by_event_id',sessions:'append_only_by_session_id',records:'maximum_valid_value',unlocks:'monotonic_false_to_true',mastery:'merge_evidence_then_recalculate',settings:'highest_revision_then_updated_at'});
function mergeConflict(kind,local,remote){switch(kind){case'records':return Number(local?.value)>=Number(remote?.value)?local:remote;case'unlocks':return local?.unlockedAt?local:remote;case'settings':return Number(local?.revision)>Number(remote?.revision)?local:Number(remote?.revision)>Number(local?.revision)?remote:new Date(local?.updatedAt||0)>=new Date(remote?.updatedAt||0)?local:remote;case'attempts':case'sessions':{const all=[...(local||[]),...(remote||[])],seen=new Set();return all.filter(v=>v?.id&&!seen.has(v.id)&&seen.add(v.id));}case'mastery':{const evidence=mergeConflict('attempts',local?.evidence||[],remote?.evidence||[]);return{contentId:local?.contentId||remote?.contentId,evidence,needsRecalculation:true};}default:throw new Error(`Política ausente: ${kind}`);}}
function aggregateSessions(rows,previousDays={}){const totals={},ordered=[...(rows||[])].sort((a,b)=>new Date(b.started_at||b.startedAt||0)-new Date(a.started_at||a.startedAt||0));for(const row of ordered){const summary=row.summary||{};if(summary.excludeFromDaily)continue;const key=summary.dateKey||String(row.started_at||row.startedAt||'').slice(0,10);if(!key)continue;const total=totals[key]||(totals[key]={hits:0,misses:0,vocabulary:{hits:0,misses:0,errors:{},wordLabels:{}}});total.hits+=Number(summary.hits)||0;total.misses+=Number(summary.errors)||0;if(row.mode==='vocabulary'){total.vocabulary.hits+=Number(summary.hits)||0;total.vocabulary.misses+=Number(summary.errors)||0;for(const error of summary.wrongAnswers||[]){const label=error.symbol||error.correct;if(!label)continue;total.vocabulary.errors[label]=(total.vocabulary.errors[label]||0)+1;total.vocabulary.wordLabels[label]=label;}}}const days={};for(const[key,total]of Object.entries(totals)){const oldVocab=previousDays[key]?.vocabulary||{};days[key]={hits:total.hits,misses:total.misses};if(total.vocabulary.hits||total.vocabulary.misses)days[key].vocabulary={...oldVocab,hits:total.vocabulary.hits,misses:total.vocabulary.misses,errors:total.vocabulary.errors,wordLabels:total.vocabulary.wordLabels,newWords:oldVocab.newWords||{}};}const latest=ordered.find(row=>Number(row.summary?.attempts)>0&&!row.summary?.excludeFromDaily)||null;return{days,last:latest?{hits:Number(latest.summary.hits)||0,misses:Number(latest.summary.errors)||0,mode:latest.mode,errors:latest.summary.wrongAnswers||[]}:null};}

class SyncQueue{constructor(store){this.store=store;}list(){return this.store.read(QUEUE_KEY,[]);}enqueue(operation){const queue=this.list();if(queue.some(item=>item.id===operation.id))return operation;const item={id:operation.id||uuid(),ownerId:operation.ownerId||null,kind:operation.kind,entityId:operation.entityId,payload:clone(operation.payload),createdAt:operation.createdAt||nowIso(),attempts:0,nextAttemptAt:null};queue.push(item);this.store.write(QUEUE_KEY,queue);return item;}upsert(operation){const queue=this.list().filter(item=>!(item.ownerId===(operation.ownerId||null)&&item.kind===operation.kind&&item.entityId===operation.entityId));this.store.write(QUEUE_KEY,queue);return this.enqueue(operation);}clear(){this.store.write(QUEUE_KEY,[]);}claimUnowned(ownerId){const queue=this.list().map(item=>item.ownerId?item:{...item,ownerId});this.store.write(QUEUE_KEY,queue);return queue.filter(item=>item.ownerId===ownerId).length;}release(ownerId){const queue=this.list().map(item=>item.ownerId===ownerId?{...item,nextAttemptAt:null}:item);this.store.write(QUEUE_KEY,queue);return queue.filter(item=>item.ownerId===ownerId).length;}renew(ids){const set=new Set(ids),queue=this.list().map(item=>set.has(item.id)?{...item,id:uuid(),attempts:0,nextAttemptAt:null,createdAt:nowIso()}:item);this.store.write(QUEUE_KEY,queue);return queue.filter(item=>set.has(item.id)).length;}ack(ids){const set=new Set(ids);this.store.write(QUEUE_KEY,this.list().filter(item=>!set.has(item.id)));}fail(ids,clock=Date.now){const set=new Set(ids),queue=this.list().map(item=>{if(!set.has(item.id))return item;const attempts=(item.attempts||0)+1;return{...item,attempts,nextAttemptAt:new Date(clock()+Math.min(60000,1000*2**attempts)).toISOString()};});this.store.write(QUEUE_KEY,queue);}batch(limit=100,clock=Date.now,ownerId=null){const now=clock();return this.list().filter(item=>(!ownerId||item.ownerId===ownerId)&&(!item.nextAttemptAt||new Date(item.nextAttemptAt).getTime()<=now)).slice(0,limit);}}
class SyncCoordinator{constructor(queue,remote,logger=new Logger(),ownerId=null){this.queue=queue;this.remote=remote;this.logger=logger;this.ownerId=ownerId;this.running=false;}async flush(){if(this.running||!this.remote)return{status:'idle'};const batch=this.queue.batch(100,Date.now,this.ownerId);if(!batch.length)return{status:'empty'};this.running=true;try{const result=await this.remote.pushBatch(batch);const accepted=result.acceptedIds||batch.map(item=>item.id);this.queue.ack(accepted);return{status:'synced',count:accepted.length};}catch(error){this.queue.fail(batch.map(item=>item.id));this.logger.error('sync_failed',error,{count:batch.length});return{status:'pending',count:batch.length};}finally{this.running=false;}}}

class SupabaseRemoteRepository{constructor(config,fetcher){if(!config?.url||!config?.anonKey)throw new Error('Configuração Supabase ausente');this.url=config.url.replace(/\/$/,'');this.anonKey=config.anonKey;this.fetcher=fetcher||((...args)=>globalThis.fetch(...args));this.accessToken=config.accessToken||null;}headers(){return{'Content-Type':'application/json',apikey:this.anonKey,Authorization:`Bearer ${this.accessToken||this.anonKey}`};}async pushBatch(operations){const response=await this.fetcher(`${this.url}/rest/v1/rpc/apply_sync_batch`,{method:'POST',headers:this.headers(),body:JSON.stringify({operations}),cache:'no-store'});if(!response.ok){const detail=await response.text().catch(()=>'');throw new Error(`sync_http_${response.status}${detail?`:${detail.slice(0,300)}`:''}`);}return response.json();}}
